def figure(label, filename, caption, note, width=r"\linewidth"):
 return rf"""
\begin{{figure}}[!htbp]
\centering
\includegraphics[width={width}]{{supplement/figures/{filename}.png}}
\caption{{{caption}}}\label{{fig:{label}}}
\begin{{minipage}}{{.98\linewidth}}\footnotesize
{note}
\end{{minipage}}
\end{{figure}}
"""


